using VisionEditor;
using VisionWorkbench;
namespace VisionUi.Checks;
static class Program {
 [STAThread] static int Main(string[] args){ApplicationConfiguration.Initialize();if(args.Length!=2){Console.Error.WriteLine("VisionUi.Checks editor|workbench <output.png>");return 2;}string path=Path.GetFullPath(args[1]);Directory.CreateDirectory(Path.GetDirectoryName(path)!);try{if(args[0]=="tools"){using var form=new EditorForm();form.CaptureTools(path);}else if(args[0]=="routes"){using var form=new EditorForm();form.CaptureRouteScenes(path);}else if(args[0]=="shell"){using var form=new EditorForm();form.CaptureShell(path);}else if(args[0]=="editor"){using var form=new EditorForm();form.RunSmoke(path);}else if(args[0]=="workbench"){using var form=new MainForm();form.LoadDemo();form.VerifyPlanPersistenceForSmoke(path+".vplan.json");form.RunSynchronouslyForSmoke();form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-30000,-30000);form.Show();Application.DoEvents();using var bitmap=new Bitmap(form.Width,form.Height);form.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));bitmap.Save(path,System.Drawing.Imaging.ImageFormat.Png);form.Close();}else throw new ArgumentException("Unknown UI target.");Console.WriteLine("UI checks and preview export passed: "+path);return 0;}catch(Exception ex){File.WriteAllText(path+".error.txt",ex.ToString());Console.Error.WriteLine(ex);return 1;}}
}
